INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'c26d0fc5-90d4-5f8d-bb57-4f7b9fe4bb31', '76aa616f-843c-531b-97c3-f1694e0496ea',
  'Hãy hiện thực lớp **Complex** để thể hiện số phức, với các phương thức sau đây được cung cấp:

- Constructor với tối đa hai thông số tương ứng phần thực và phần ảo, khuyết một thông số thì thông số đó bằng 0.0.
- **getModulus** để trả về giá trị modulo của số phức.
- Các toán tử `>`, `>=`, `<`, `<=`, `==`, `!=` để so sánh hai số phức dựa trên modulo.
- **toString** để trả về số phức dưới dạng chuỗi đại số ($a + b * i$).

**For example:**

| Test | Result |
| :--- | :--- |
| `Complex a(1, 5);`<br>`cout << a.getModulus();` | `5.09902` |', 1
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '36ac5d34-056f-5971-8193-29c13e293a01', '76aa616f-843c-531b-97c3-f1694e0496ea',
  'Hãy hiện thực các phương thức `sort` của lớp `StraightSelectionSort` để các phương thức này có thể sắp xếp tăng dần với dữ liệu là mảng các phần tử có kiểu `Complex`:

- Phương thức `static void sort(Complex *list, int length)`: sắp xếp toàn bộ phần tử trong `list`.
- Phương thức `static void sort(Complex *list, int length, int left, int right)`: sắp xếp các phần tử có chỉ số nằm trong đoạn `[left, right]` (không cần kiểm tra tính đúng đắn của các giá trị truyền vào).

Sinh viên phải sử dụng mã giả đã được viết trong slide để viết thành mã thật.

**For example:**

| Test | Result |
| :--- | :--- |
| `int length = 5;` | `3 - 1 * i: 3.16228` |
| `Complex *list = new Complex[5];` | `-2 + 4 * i: 4.47214` |
| `list[0] = Complex(3, -1);` | `5 + 2 * i: 5.38516` |
| `list[1] = Complex(5, 2);` | `1 - 7 * i: 7.07107` |
| `list[2] = Complex(1, -7);` | `6 + 8 * i: 10` |
| `list[3] = Complex(6, 8);` | `Number of comparision (on Complex): 10` |
| `list[4] = Complex(-2, 4);` | |
| `StraightSelectionSort::sort(list, length);` | |', 2
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '0d798fbb-3c0a-58c6-8fb9-ce2108e7be53', '76aa616f-843c-531b-97c3-f1694e0496ea',
